mapper.select:
select T_Code
from Outline_Datasource_Temp
where Od_Id = #{odId}

select mn.*, od.Od_Name, od.Od_Type, od.Od_Source, od.Od_Status, od.Od_Remark, od.Od_Address, od.Od_Method, od.Od_Body, od.od_alias from Outline_Projec_Datasource mn left join Outline_Datasource od on od.id=mn.od_id where mn.opl_id in
#{item}
order by mn.Create_Time desc

select mn.*,
od.Od_Name as odName,
od.Od_Type as odType,
od.Od_Source as odSource,
od.Od_Status as odStatus,
od.Od_Remark as odRemark,
od.Od_Address as odAddress,
od.Od_Method as odMethod,
od.Od_Body as odBody,
od.od_alias as odAlias
from Outline_Projec_Datasource mn
left join Outline_Datasource od on od.id=mn.od_id

    
        and mn.id = #{params.id}
    
    
        and mn.opl_id = #{params.oplId}
    
    
        and mn.od_name = #{params.odName}
    
    
        and mn.od_type = #{params.odType}
    
    
        and mn.od_source = #{params.odSource}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
